const digest = (buffer) => createHash("sha256").update(buffer).digest("hex");

async function readMaybe(file) {
  try { return await readFile(file); } catch (error) {
    if (error?.code === "ENOENT") return null;
    throw error;
  }
}

const states = [];
for (const file of Object.keys(TARGET)) {
  const current = await readMaybe(file);
  const currentHash = current ? digest(current) : null;
  if (currentHash === TARGET[file]) {
    states.push([file, "target"]);
    continue;
  }
  if (currentHash === EXPECTED[file]) {
    states.push([file, "baseline"]);
    continue;
  }
  throw new Error(`Sicherheitsstopp: ${file} entspricht weder dem geprüften 4.6.1-Ausgangsstand noch dem fertigen 4.6.2-Zielstand. Es wurde nichts geändert.`);
}

let changed = 0;
for (const [file, state] of states) {
  if (state === "target") continue;
  await mkdir(dirname(file), { recursive: true });
  const content = gunzipSync(Buffer.from(PAYLOAD[file], "base64"));
  if (digest(content) !== TARGET[file]) throw new Error(`Interner Payload-Fehler bei ${file}.`);
  await writeFile(file, content);
  changed += 1;
  console.log(`✓ ${file} aktualisiert`);
}

for (const file of Object.keys(TARGET)) {
  const current = await readFile(file);
  if (digest(current) !== TARGET[file]) throw new Error(`Nachprüfung fehlgeschlagen: ${file}.`);
}

console.log(`✓ Legacy Mirror Repair 4.6.2 angewendet: ${changed} Datei(en) geändert.`);
console.log("✓ Alle Zieldateien SHA-256-geprüft.");
